#!/usr/bin/env node
// Generated by Keel — evidence retention for .keel/evidence/{security,design}/<branch>/<run>/.
// Copy to .keel/prune-evidence.mjs. Dry run by default; --apply deletes, then commit the result.
// Rules (tune in .keel/meta.json "evidenceRetention"):
//   keep the newest `keepRunsPerBranch` runs of each branch (default 3);
//   a branch merged into main, or deleted, whose newest run is older than
//   `pruneMergedAfterDays` (default 30) loses its whole folder.
// Never touched: .keel/evidence/*.json gate records, phase-N/ and chg-xxx/ artefact folders
// (exit gates cite them), and any `ledger/` folder (the next security run reuses it).
// Branch folder names are the branch with "/" written as "__". Run folders start YYYY-MM-DD.
// Self-test: node .keel/prune-evidence.mjs --self-test
import { readdirSync, readFileSync, rmSync, existsSync } from 'fs'
import { execSync } from 'child_process'
import { join } from 'path'

// tree: { kind: { branchDir: [runDir, ...] } } → list of paths to delete
export function plan(tree, { live, merged, now, keepRunsPerBranch = 3, pruneMergedAfterDays = 30 }) {
  const out = []
  for (const [kind, branches] of Object.entries(tree)) {
    for (const [dir, runs] of Object.entries(branches)) {
      if (dir === 'ledger') continue
      const branch = dir.replaceAll('__', '/')
      const sorted = runs.filter(r => r !== 'ledger').sort().reverse()
      const newest = Date.parse(sorted[0]?.slice(0, 10))
      const done = branch !== 'main' && (merged.has(branch) || !live.has(branch)) // main is never "done"
      if (done && newest && (now - newest) / 864e5 > pruneMergedAfterDays) { out.push(join(kind, dir)); continue }
      sorted.slice(keepRunsPerBranch).forEach(r => out.push(join(kind, dir, r)))
    }
  }
  return out
}

if (process.argv.includes('--self-test')) {
  const now = Date.parse('2026-10-31')
  const got = plan({
    security: { ledger: [], main: ['2026-01-01', '2026-01-02', '2026-01-03', '2026-01-04'],
      'feat__a': ['2026-09-01'], 'feat__b': ['2026-10-30', 'ledger'] },
    design: { 'feat__a': ['2026-10-29'] },
  }, { live: new Set(['main', 'feat/a', 'feat/b']), merged: new Set(['main', 'feat/a']), now })
  const want = ['security/main/2026-01-01', 'security/feat__a']
  const ok = JSON.stringify(got) === JSON.stringify(want)
  console.log(ok ? 'ok' : 'FAIL ' + JSON.stringify(got)); process.exit(ok ? 0 : 1)
}

const root = '.keel/evidence'
const ls = d => existsSync(d) ? readdirSync(d, { withFileTypes: true }).filter(e => e.isDirectory()).map(e => e.name) : []
const git = c => execSync(c, { encoding: 'utf8' }).split('\n').map(s => s.replace(/^[*+ ]+/, '').trim()).filter(Boolean)
let cfg = {}
try { cfg = JSON.parse(readFileSync('.keel/meta.json', 'utf8')).evidenceRetention || {} } catch {}
const tree = {}
for (const kind of ['security', 'design']) {
  tree[kind] = {}
  for (const b of ls(join(root, kind))) tree[kind][b] = ls(join(root, kind, b))
}
const doomed = plan(tree, { ...cfg, live: new Set(git('git branch --list')), merged: new Set(git('git branch --merged main')), now: Date.now() })
const apply = process.argv.includes('--apply')
for (const p of doomed) { console.log((apply ? 'deleted ' : 'would delete ') + join(root, p)); if (apply) rmSync(join(root, p), { recursive: true }) }
if (!doomed.length) console.log('evidence retention: nothing to prune')
